252	        String telephone = normalize(owner.getTelephone());
253	        return ownerRepository.findAll().stream()
254	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
255	                && Objects.equals(normalize(existing.getTelephone()), telephone));
256	    }
