258	    private boolean isDuplicateEmail(Owner owner) {
259	        String email = owner.getEmail();
260	        if (email == null || email.isBlank()) {
261	            return false;
262	        }
263	        String normalizedEmail = normalize(email);
264	        return ownerRepository.findAll().stream()
