269	    /**
270	     * Normalize a textual value for duplicate detection so that comparisons
271	     * ignore letter case and surrounding or repeated whitespace. A {@code null}
272	     * value stays {@code null}; otherwise surrounding whitespace is trimmed, any
273	     * run of internal whitespace is collapsed to a single space, and letters are
274	     * lower-cased. For example "  john   smith " and "John Smith" normalize to
275	     * the same value and therefore count as the same person.
276	     */
277	    private static String normalize(String value) {
278	        if (value == null) {
279	            return null;
280	        }
281	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
282	    }
